class LawCrawlerTests(unittest.TestCase):
    def setUp(self):
        self.assertIsNotNone(importlib.util.find_spec("zhilv_qiling_v2.law_crawler"), "official crawler has not been implemented")
        self.crawler = importlib.import_module("zhilv_qiling_v2.law_crawler")
        self.library = importlib.import_module("zhilv_qiling_v2.law_library")
        self.raw = zlib.decompress(base64.b85decode(OFFICIAL_HTML_B85))
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.lib = self.library.LawLibrary(Path(self.tmp.name) / "laws.sqlite")

    def test_real_official_html_preserves_articles_and_unknown_validity(self):
        self.assertEqual(hashlib.sha256(self.raw).hexdigest(), "3c7f35720c3f3deb8da6c4ca594c4cf89d08faf62d23f300a6cecbb8845c3714")
        parsed = self.crawler.extract_document(self.raw, URL)
        self.assertIn("政府采购质疑和投诉办法", parsed["document"]["title"])
        self.assertEqual(len(parsed["articles"]), 45)
        self.assertEqual(parsed["articles"][0]["article_no"], "第一条")
        self.assertIn("为了规范政府采购质疑和投诉行为", parsed["articles"][0]["content"])
        self.assertEqual(parsed["document"]["validity"], "unknown")
        self.assertEqual(parsed["document"]["effective_from"], "2018-03-01")
        self.assertTrue(parsed["document"]["date_evidence"])

    def test_chapter_titles_and_related_articles_are_not_quoted_as_law(self):
        parsed = self.crawler.extract_document(self.raw, URL)
        self.assertNotIn("第二章", parsed["articles"][8]["content"])
        self.assertIn("第二章", parsed["articles"][9]["location"]["section_heading"])
        self.assertNotIn("相关稿件", parsed["articles"][-1]["content"])

    def test_mofcom_original_article_excludes_adjacent_policy_sidebar(self):
        raw = zlib.decompress(base64.b85decode(MOFCOM_HTML_B85))
        parsed = self.crawler.extract_document(raw, "https://www.mofcom.gov.cn/zcfb/zgdwjjmywg/art/2015/art_2338501d371740929e5c2114efa4cfae.html")
        self.assertEqual(len(parsed["articles"]), 79)
        self.assertEqual(parsed["articles"][-1]["content"], "第七十九条本条例自2015年3月1日起施行。")

    def test_gb18030_decoding_and_numbered_units(self):
        raw = '<html><head><meta charset="gb2312"><title>建设工程管理办法</title></head><body><article><h1>建设工程管理办法</h1><p>一、建设单位应当依法履行工程建设管理职责，保障施工质量与安全。</p><p>二、工程建设应当遵守有关法律法规，维护当事人的合法权益。</p></article></body></html>'.encode("gb18030")
        parsed = self.crawler.extract_document(raw, "https://www.mohurd.gov.cn/test.html")
        self.assertEqual(len(parsed["articles"]), 2)
        self.assertEqual(parsed["document"]["title"], "建设工程管理办法")

    def test_empty_content_container_does_not_hide_numbered_legal_units(self):
        raw = ('<html><title>建设工程管理办法</title><body><main>'
            '<div class="content"></div><p>一、建设单位应当依法履行工程建设管理职责，保障施工质量与安全。</p>'
            '<p>二、工程建设应当遵守有关法律法规，维护当事人的合法权益。</p>'
            '</main></body></html>').encode()
        parsed = self.crawler.extract_document(raw, "https://www.mohurd.gov.cn/test.html")
        self.assertEqual(len(parsed["articles"]), 2)
        self.assertIn("保障施工质量与安全", parsed["articles"][0]["content"])

    def test_input_named_article_content_cannot_mask_real_body(self):
        # Regression from court.gov.cn/zixun/xiangqing/233181.html's actual search input.
        raw = '<html><head><title>中华人民共和国民法典 - 中华人民共和国最高人民法院</title></head><body><input class="btn" id="article_content" type="submit"><div class="txt"><p>第一条 为了保护民事主体的合法权益，调整民事关系，维护社会和经济秩序，根据宪法，制定本法。</p><p>第二条 民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。</p></div></body></html>'.encode()
        parsed = self.crawler.extract_document(raw, "https://www.court.gov.cn/zixun/xiangqing/233181.html")
        self.assertEqual(len(parsed["articles"]), 2)
        self.assertEqual(parsed["document"]["title"], "中华人民共和国民法典")

    def test_homepage_captcha_error_and_binary_are_rejected(self):
        fixtures = [b"%PDF-1.7 not html", '<html><title>中国政府网首页</title><nav>第一条 法律法规政策文件新闻公开办事服务网站导航信息链接。</nav></html>'.encode(), '<html><title>安全验证</title><article>验证码，请完成安全验证后继续访问。</article></html>'.encode(), '<html><title>页面不存在</title><body>404 Not Found</body></html>'.encode()]
        for raw in fixtures:
            with self.subTest(raw=raw[:30]), self.assertRaises(self.library.LawError):
                self.crawler.extract_document(raw, URL)

    def test_private_local_unofficial_and_disguised_urls_blocked(self):
        forbidden = ["file:///etc/passwd", "http://localhost/x", "http://127.0.0.1/x", "https://gov.cn.evil.example/x", "https://www.gov.cn@evil.example/x", "https://www.gov.cn:444/x", "https://www.gov.cn\\@evil.example/x"]
        for url in forbidden:
            with self.subTest(url=url), self.assertRaises(self.library.LawError):
                self.crawler._validate_url(url)
        with patch.object(self.crawler.socket, "getaddrinfo", return_value=[(2, 1, 6, "", ("10.1.2.3", 443))]):
            with self.assertRaises(self.library.LawError): self.crawler._validate_url(URL)

    def test_redirect_to_private_or_nonofficial_is_not_fetched(self):
        for redirect in ("http://127.0.0.1/secret", "https://attacker.example/payload"):
            calls = []
            def transport(url, timeout, max_bytes, addresses):
                calls.append(url)
                return {"status": 302, "headers": {"location": redirect}, "content": b""}
            with patch.object(self.crawler, "_public_addresses", return_value=["1.1.1.1"]):
                with self.assertRaises(self.library.LawError): self.crawler._fetch(URL, transport=transport)
            self.assertEqual(calls, [URL])

    def test_streaming_size_limit_rejects_even_injected_transport(self):
        with patch.object(self.crawler, "_public_addresses", return_value=["1.1.1.1"]):
            with self.assertRaises(self.library.LawError):
                self.crawler._fetch(URL, max_bytes=5, transport=lambda *args: {"status": 200, "headers": {"content-type": "text/html"}, "content": b"123456"})

    def test_crawl_persists_real_success_draft_and_failure_receipt(self):
        catalog = [{"id": "official", "name": "官方法规", "domains": ["procurement"], "urls": [URL, "https://www.gov.cn/missing.htm"]}]
        def transport(url, *args):
            if url.endswith("missing.htm"): return {"status": 404, "headers": {}, "content": b"not found"}
            return {"status": 200, "headers": {"content-type": "text/html; charset=utf-8"}, "content": self.raw}
        with patch.object(self.crawler, "source_catalog", return_value=catalog), patch.object(self.crawler, "_transport", side_effect=transport), patch.object(self.crawler, "_public_addresses", return_value=["1.1.1.1"]), patch.object(self.crawler, "_throttle"):
            result = self.crawler.crawl_sources(self.lib, ADMIN, source_ids=["official"], max_documents=2)
        self.assertEqual((result["attempted"], result["succeeded"], result["failed"]), (2, 1, 1))
        self.assertEqual(result["status"], "partial")
        run = self.library.LawLibrary(self.lib.path).list_crawl_runs()["items"][0]
        self.assertEqual(run["run_id"], result["run_id"])
        self.assertIn("404", run["results"][1]["error"])
        self.assertEqual(self.lib.stats()["documents"], 0)
        self.assertEqual(self.lib.stats(include_unpublished=True)["articles"], 45)

    def test_crawl_bounds_and_permissions_checked_before_network(self):
        for kwargs in ({"max_documents": 51}, {"timeout": 31}, {"max_documents": 0}, {"source_ids": ["missing-source"]}):
            with self.assertRaises(self.library.LawError): self.crawler.crawl_sources(self.lib, ADMIN, **kwargs)
        with self.assertRaises(self.library.LawError): self.crawler.crawl_sources(self.lib, {"user_id": "r", "role": "user"})

    def test_catalog_covers_all_domains_and_only_official_urls(self):
        catalog = self.crawler.source_catalog()
        self.assertTrue(set(self.library.DOMAINS).issubset({d for source in catalog for d in source["domains"]}))
        for source in catalog:
            self.assertTrue(source["urls"])
            for url in source["urls"]: self.crawler._validate_url(url, resolve=False)


